<?php
require __DIR__.'/config.php';
if(empty($_SESSION['cart'])){header('Location: carrinho.php');exit;}
function get_cart_items(){ $items=[];$sum=0;foreach($_SESSION['cart'] as $vid=>$qty){$s=db()->prepare("SELECT v.*,p.nome,p.preco,p.preco_promocional,p.ativo FROM variantes_estoque v JOIN produtos p ON p.id=v.produto_id WHERE v.id=? AND v.estoque>=?");$s->execute([(int)$vid,(int)$qty]);$r=$s->fetch();if(!$r||!$r['ativo'])throw new RuntimeException('Um item ficou indisponível. Volte ao carrinho e revise.');$r['qty']=(int)$qty;$r['unit']=$r['preco_promocional']!==null?(float)$r['preco_promocional']:(float)$r['preco'];$sum+=$r['qty']*$r['unit'];$items[]=$r;}return [$items,$sum];}
$error='';try{[$items,$subtotal]=get_cart_items();}catch(Throwable $e){$items=[];$subtotal=0;$error=$e->getMessage();}
if($_SERVER['REQUEST_METHOD']==='POST'&&!$error){csrf_check();try{
$name=trim($_POST['nome']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$phone=trim($_POST['telefone']??'');$cep=trim($_POST['cep']??'');$address=trim($_POST['endereco']??'');$number=trim($_POST['numero']??'');$comp=trim($_POST['complemento']??'');$city=trim($_POST['cidade']??'');$state=strtoupper(trim($_POST['estado']??''));$pay=$_POST['pagamento']??'';
if(!$name||!$email||!$cep||!$address||!$number||!$city||!preg_match('/^[A-Z]{2}$/',$state)||!in_array($pay,['Pix','Cartão','Na entrega'],true))throw new RuntimeException('Preencha corretamente todos os campos obrigatórios.');
$pdo=db();$pdo->beginTransaction();
$cs=$pdo->prepare("INSERT INTO clientes(nome,email,telefone) VALUES(?,?,?)");$cs->execute([$name,$email,$phone]);$cid=(int)$pdo->lastInsertId();
$code='BY'.date('ymd').strtoupper(bin2hex(random_bytes(3)));$frete=0;$total=$subtotal+$frete;
$os=$pdo->prepare("INSERT INTO pedidos(codigo,cliente_id,cliente_nome,email,telefone,cep,endereco,numero,complemento,cidade,estado,forma_pagamento,status,subtotal,frete,total) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");
$os->execute([$code,$cid,$name,$email,$phone,$cep,$address,$number,$comp,$city,$state,$pay,'Recebido',$subtotal,$frete,$total]);$oid=(int)$pdo->lastInsertId();
foreach($items as $it){$ins=$pdo->prepare("INSERT INTO itens_pedido(pedido_id,produto_id,produto_nome,tamanho,cor,quantidade,preco_unitario) VALUES(?,?,?,?,?,?,?)");$ins->execute([$oid,$it['produto_id'],$it['nome'],$it['tamanho'],$it['cor'],$it['qty'],$it['unit']]);$up=$pdo->prepare("UPDATE variantes_estoque SET estoque=estoque-? WHERE id=? AND estoque>=?");$up->execute([$it['qty'],$it['id'],$it['qty']]);if(!$up->rowCount())throw new RuntimeException('Estoque alterado durante a compra. Tente novamente.');}
$pdo->commit();$_SESSION['last_order']=$code;$_SESSION['cart']=[];header('Location: pedido.php?codigo='.urlencode($code));exit;
}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException?'Não foi possível registrar o pedido. Confira os dados e tente novamente.':$e->getMessage();}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Finalizar compra | Loja BY</title><link rel="stylesheet" href="style.css"></head><body><header class="top"><a class="brand" href="index.php"><span class="logo">BY</span><span>LOJA BY<small>SUA MARCA, SEU ESTILO</small></span></a><a href="carrinho.php">Voltar ao carrinho</a></header><main class="wrap"><h1>Finalizar compra</h1><?php if($error):?><div class="notice error"><?=h($error)?></div><?php endif?><div class="card"><h2>Resumo: <?=money($subtotal)?></h2><p class="muted">Este projeto registra o pedido, mas ainda não cobra pagamentos nem calcula frete automaticamente. Configure um gateway antes de vender de verdade.</p><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div class="form-grid"><?php foreach(['nome'=>'Nome completo','email'=>'E-mail','telefone'=>'Telefone/WhatsApp','cep'=>'CEP','endereco'=>'Rua / Avenida','numero'=>'Número','complemento'=>'Complemento (opcional)','cidade'=>'Cidade','estado'=>'UF'] as $k=>$label):?><div class="field <?=$k==='endereco'?'wide':''?>"><label><?=$label?></label><input name="<?=$k?>" <?=$k!=='complemento'?'required':''?> <?=$k==='email'?'type="email"':($k==='cep'?'placeholder="00000-000"':'')?>></div><?php endforeach?><div class="field wide"><label>Forma de pagamento preferida</label><select name="pagamento" required><option value="">Selecione</option><option>Pix</option><option>Cartão</option><option>Na entrega</option></select></div></div><p><button class="btn">Registrar pedido</button></p></form></div></main><footer class="footer">LOJA BY</footer></body></html>
